"""
Independent verification path for tests/fixtures/expectedResults.json.

Recomputes every expected value straight from the supplied dataset
(data/dataset.json) using Python and exact fractions — a separate calculation
path from the JavaScript domain code in src/domain/.

Usage (from the project root):
    python3 tests/fixtures/verify_expected_results.py           # check the fixture
    python3 tests/fixtures/verify_expected_results.py --write   # regenerate it

Not imported by the application or by the Vitest suite.
"""

import json
import sys
from fractions import Fraction
from math import floor
from pathlib import Path

ROOT = Path(__file__).resolve().parents[2]
DATASET = ROOT / "data" / "dataset.json"
RUNTIME_COPY = ROOT / "src" / "data" / "cityData.json"
FIXTURE = Path(__file__).resolve().parent / "expectedResults.json"

BUDGET_WHAT_IF = 41000
IMPORTANCE_WHAT_IF = ("PLACE_GILDED_01", 2)
NO_AFFORDABLE_BUDGET = 17999


def one_decimal_half_up(total, importance_total):
    # Exact rational average, rounded half-up to tenths.
    tenths = floor(Fraction(total * 10, importance_total) + Fraction(1, 2))
    return f"{tenths // 10}.{tenths % 10}"


def evaluate(city, budget, importance):
    importance_total = sum(importance.values())
    results = []
    for hotel in city["hotels"]:
        total = sum(importance[pid] * minutes for pid, minutes in hotel["round_trip_minutes"].items())
        affordable = hotel["stay_cost"] <= budget
        results.append({
            "hotel_id": hotel["id"],
            "hotel_name": hotel["name"],
            "stay_cost": hotel["stay_cost"],
            "weighted_travel_total": total,
            "weighted_average_display": one_decimal_half_up(total, importance_total),
            "affordable": affordable,
            "remaining_budget": budget - hotel["stay_cost"] if affordable else None,
            "budget_shortfall": None if affordable else hotel["stay_cost"] - budget,
            "rank": None,
        })
    ranked = sorted((r for r in results if r["affordable"]),
                    key=lambda r: (r["weighted_travel_total"], r["stay_cost"], r["hotel_id"]))
    for position, result in enumerate(ranked, start=1):
        result["rank"] = position
    ranking = [r["hotel_id"] for r in ranked]
    return {
        "budget": budget,
        "importance_total": importance_total,
        "status": "RECOMMENDATION_FOUND" if ranking else "NO_AFFORDABLE_HOTEL",
        "recommended_hotel": ranking[0] if ranking else None,
        "ranking": ranking,
        "results": results,
    }


def build_expected():
    city = json.loads(DATASET.read_text())["city"]
    hotels, places = city["hotels"], city["wishlist_places"]
    base_importance = {p["id"]: p["importance"] for p in places}

    initial = evaluate(city, city["initial_budget"], base_importance)
    affordable = [r for r in initial["results"] if r["affordable"]]
    max_trip = {h["id"]: max(h["round_trip_minutes"].values()) for h in hotels}

    place_id, new_value = IMPORTANCE_WHAT_IF
    changed_importance = {**base_importance, place_id: new_value}
    place_name = next(p["name"] for p in places if p["id"] == place_id)

    return {
        "scenario": "Aura Hotel Base-Camp Comparator",
        "source": "Generated by tests/fixtures/verify_expected_results.py from data/dataset.json. Test-only: never import into src/.",
        "dataset_summary": {
            "hotel_count": len(hotels),
            "wishlist_place_count": len(places),
            "marker_count": len(hotels) + len(places),
            "travel_time_entries": sum(len(h["round_trip_minutes"]) for h in hotels),
            "attraction_count": sum(p["type"] == "attraction" for p in places),
            "food_count": sum(p["type"] == "food" for p in places),
            "distinct_importance_values": sorted(set(base_importance.values())),
        },
        "initial": {
            **initial,
            "affordable_hotel_count": len(affordable),
            "cheapest_affordable_hotel": min(affordable, key=lambda r: r["stay_cost"])["hotel_id"],
            "most_accessible_hotel": min(initial["results"], key=lambda r: r["weighted_travel_total"])["hotel_id"],
            "max_round_trip_minutes": max_trip,
        },
        "budget_what_if": evaluate(city, BUDGET_WHAT_IF, base_importance),
        "budget_one_below_what_if": evaluate(city, BUDGET_WHAT_IF - 1, base_importance),
        "importance_what_if": {
            "place_id": place_id,
            "place_name": place_name,
            "original_importance": base_importance[place_id],
            "new_importance": new_value,
            **evaluate(city, city["initial_budget"], changed_importance),
        },
        "no_affordable": evaluate(city, NO_AFFORDABLE_BUDGET, base_importance),
    }


def main():
    if DATASET.read_bytes() != RUNTIME_COPY.read_bytes():
        sys.exit("FAIL: src/data/cityData.json differs from the supplied data/dataset.json")

    expected = build_expected()
    if "--write" in sys.argv:
        FIXTURE.write_text(json.dumps(expected, indent=2, ensure_ascii=False) + "\n")
        print(f"Wrote {FIXTURE.relative_to(ROOT)}")
        return

    if json.loads(FIXTURE.read_text()) != expected:
        sys.exit("FAIL: expectedResults.json does not match the independent calculation")
    print("OK: expectedResults.json matches the independent calculation")


if __name__ == "__main__":
    main()
